#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 100005

char P[MAXN];
int divisors[MAXN];

int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    if (scanf("%s", P) != 1) return 0;

    int num_divisors = 0;
    for (int i = 1; i * i <= N; ++i) {
        if (N % i == 0) {
            if (i < N) {
                divisors[num_divisors++] = i;
            }
            int other = N / i;
            if (other != i && other < N) {
                divisors[num_divisors++] = other;
            }
        }
    }

    qsort(divisors, num_divisors, sizeof(int), cmp);

    int count_base[26];
    int count_curr[26];

    for (int d = 0; d < num_divisors; ++d) {
        int L = divisors[d];
        int K = N / L;

        memset(count_base, 0, sizeof(count_base));
        for (int j = 0; j < L; ++j) {
            count_base[P[j] - 'a']++;
        }

        bool ok = true;
        for (int i = 1; i < K; ++i) {
            memset(count_curr, 0, sizeof(count_curr));
            int offset = i * L;
            for (int j = 0; j < L; ++j) {
                count_curr[P[offset + j] - 'a']++;
            }
            for (int c = 0; c < 26; ++c) {
                if (count_curr[c] != count_base[c]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) {
                break;
            }
        }

        if (ok) {
            P[L] = '\0';
            printf("%s\n", P);
            return 0;
        }
    }

    printf("*\n");
    return 0;
}
