    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char *p = (char *)malloc(n + 2);
    if (scanf("%s", p) != 1) {
        free(p);
        return 0;
    }

    // Encontrar divisores proprios de N
    int divisors[200];
    int num_div = 0;

    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            divisors[num_div++] = i;
            if (i * i != n && i != 1) {
                divisors[num_div++] = n / i;
            }
        }
    }

    qsort(divisors, num_div, sizeof(int), cmp_int);

    int count_root[26];
    int count_curr[26];

    for (int d = 0; d < num_div; d++) {
        int L = divisors[d];
        if (L >= n) continue;

        memset(count_root, 0, sizeof(count_root));
        for (int i = 0; i < L; i++) {
            count_root[p[i] - 'a']++;
        }

        int possible = 1;
        for (int i = L; i < n; i += L) {
            memset(count_curr, 0, sizeof(count_curr));
            for (int j = 0; j < L; j++) {
                count_curr[p[i + j] - 'a']++;
            }
            if (memcmp(count_root, count_curr, sizeof(count_root)) != 0) {
                possible = 0;
                break;
            }
